-- ============================================================================
-- DATOS DE DEMOSTRACION - SLIMMING GYM FITNESS
--
-- Generado el 2026-08-10 por backend-gimnasio/scripts/generar-dataset-sql.js
-- No editar a mano: se regenera desde seeders/demoData.js.
--
-- Contenido: 4 entrenadores,
-- 30 socios y su operacion de los ultimos meses:
-- suscripciones con historial de renovaciones, pagos aprobados y pendientes,
-- asistencias, rutinas, plantillas, catalogo de ejercicios, clases grupales
-- con reservas, evaluaciones fisicas, notificaciones y bitacora de correos.
--
-- Requisitos previos: los roles y los 3 planes base deben existir
-- (seeders/seedRunner.js o database/seeds/seed.sql).
--
-- No crea administradores: el unico debe ser el superusuario maestro.
--
-- Ejecucion:
--   sqlcmd -S localhost -U sa -P '<clave>' -d GymDatabase -C -f 65001 -i demo_dataset.sql
--
-- Es re-ejecutable: empieza borrando los datos demo anteriores. Todas las
-- cuentas usan el dominio @demo.slimminggym.com y la contrasena Gimnasio2026,
-- y ese dominio es lo unico que las distingue de los usuarios reales.
-- ============================================================================

SET NOCOUNT ON;
GO

-- --------------------------------------------------------------------------
-- Comprobaciones previas. Si algo falta se activa NOEXEC y el resto del
-- script no se ejecuta, en lugar de dejar los datos a medias.
-- --------------------------------------------------------------------------
IF OBJECT_ID('dbo.Users','U') IS NULL OR OBJECT_ID('dbo.Plans','U') IS NULL OR OBJECT_ID('dbo.Roles','U') IS NULL
BEGIN
    PRINT 'ERROR: faltan las tablas base (Users, Plans, Roles). Revisa la base seleccionada con -d.';
    SET NOEXEC ON;
END
GO

IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleName = 'Member')
   OR NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleName = 'Coach')
BEGIN
    PRINT 'ERROR: faltan los roles Member y Coach. Ejecuta primero el seed de datos maestros.';
    SET NOEXEC ON;
END
GO

IF (SELECT COUNT(*) FROM dbo.Plans WHERE PlanName IN (N'Plan Básico (Mensual)', N'Plan Pro (Trimestral)', N'Plan VIP (Anual)')) < 3
BEGIN
    PRINT 'ERROR: faltan los 3 planes base. Ejecuta primero el seed de datos maestros.';
    SET NOEXEC ON;
END
GO

PRINT 'Cargando datos de demostracion...';
GO

-- --------------------------------------------------------------------------
-- Borrado de una carga anterior, para que el script sea re-ejecutable.
-- --------------------------------------------------------------------------
IF OBJECT_ID('dbo.AuditLogs','U') IS NOT NULL
   AND COL_LENGTH('dbo.AuditLogs','TableName') IS NOT NULL
   AND COL_LENGTH('dbo.AuditLogs','EntityID') IS NOT NULL
BEGIN
    EXEC sp_executesql N'
        DELETE FROM dbo.AuditLogs
        WHERE TableName = ''Payments''
          AND EntityID IN (SELECT p.PaymentID FROM dbo.Payments p
                           JOIN dbo.Subscriptions s ON s.SubscriptionID = p.SubscriptionID
                           WHERE s.UserID IN (SELECT UserID FROM dbo.Users WHERE Email LIKE '%@demo.slimminggym.com'));';
END
GO
IF OBJECT_ID('dbo.WorkoutSessionDetails','U') IS NOT NULL AND OBJECT_ID('dbo.WorkoutSessions','U') IS NOT NULL AND OBJECT_ID('dbo.Users','U') IS NOT NULL
BEGIN
    DELETE FROM dbo.WorkoutSessionDetails
    WHERE SessionID IN (SELECT SessionID FROM dbo.WorkoutSessions WHERE UserID IN (SELECT UserID FROM dbo.Users WHERE Email LIKE '%@demo.slimminggym.com'));
END
GO
IF OBJECT_ID('dbo.WorkoutSessions','U') IS NOT NULL AND OBJECT_ID('dbo.Users','U') IS NOT NULL
BEGIN
    DELETE FROM dbo.WorkoutSessions WHERE UserID IN (SELECT UserID FROM dbo.Users WHERE Email LIKE '%@demo.slimminggym.com');
END
GO
