-- Catálogo de ejercicios: 30 filas
IF OBJECT_ID('dbo.ExerciseCatalog','U') IS NOT NULL
BEGIN
INSERT INTO dbo.ExerciseCatalog (Name, MuscleGroup, Description)
SELECT v.Name, v.MuscleGroup, v.Description
FROM (VALUES
    (N'Sentadilla libre', N'Piernas', N'Barra sobre trapecios, bajar hasta paralelo controlando la espalda recta.'),
    (N'Prensa de piernas', N'Piernas', N'Empuje con pies a la anchura de hombros, sin bloquear rodillas.'),
    (N'Peso muerto', N'Espalda', N'Cadera atrás, espalda neutra, barra pegada a las piernas.'),
    (N'Zancadas con mancuernas', N'Piernas', N'Paso largo, rodilla trasera cerca del piso, torso erguido.'),
    (N'Extensión de cuádriceps', N'Piernas', N'Movimiento controlado, pausa de un segundo arriba.'),
    (N'Curl femoral acostado', N'Piernas', N'Cadera pegada al banco, sin impulso lumbar.'),
    (N'Press de banca', N'Pecho', N'Escápulas retraídas, barra a la altura del pecho.'),
    (N'Press inclinado con mancuernas', N'Pecho', N'Banco a 30°, recorrido completo sin chocar mancuernas.'),
    (N'Aperturas en polea', N'Pecho', N'Codos ligeramente flexionados, apretar al centro.'),
    (N'Fondos en paralelas', N'Pecho', N'Torso ligeramente inclinado al frente, bajar hasta 90°.'),
    (N'Dominadas', N'Espalda', N'Agarre prono, llevar el pecho a la barra sin balanceo.'),
    (N'Remo con barra', N'Espalda', N'Torso a 45°, tirar hacia el ombligo.'),
    (N'Jalón al pecho', N'Espalda', N'Bajar la barra al pecho, codos hacia el piso.'),
    (N'Remo en polea baja', N'Espalda', N'Espalda fija, apretar escápulas al final.'),
    (N'Press militar', N'Hombros', N'De pie, core activo, sin arquear la lumbar.'),
    (N'Elevaciones laterales', N'Hombros', N'Subir hasta la altura del hombro, sin impulso.'),
    (N'Pájaros con mancuernas', N'Hombros', N'Torso inclinado, abrir hasta la línea de los hombros.'),
    (N'Curl de bíceps con barra', N'Brazos', N'Codos pegados al torso, bajada controlada.'),
    (N'Curl martillo', N'Brazos', N'Agarre neutro, trabaja braquial y antebrazo.'),
    (N'Extensión de tríceps en polea', N'Brazos', N'Codos fijos, extensión completa.'),
    (N'Press francés', N'Brazos', N'Barra Z, bajar hacia la frente sin mover los codos.'),
    (N'Plancha abdominal', N'Core', N'Cuerpo en línea recta, glúteo y abdomen contraídos.'),
    (N'Crunch en polea', N'Core', N'Flexionar la columna, no la cadera.'),
    (N'Elevación de piernas colgado', N'Core', N'Sin balanceo, subir hasta la cadera.'),
    (N'Burpees', N'Funcional', N'Pecho al piso, salto con palmada arriba.'),
    (N'Battle ropes', N'Funcional', N'Olas alternas, rodillas semiflexionadas.'),
    (N'Kettlebell swing', N'Funcional', N'Impulso de cadera, brazos relajados.'),
    (N'Caminadora - trote continuo', N'Cardio', N'Ritmo moderado, respiración controlada.'),
    (N'Bicicleta estática', N'Cardio', N'Resistencia media, cadencia constante.'),
    (N'Remo ergómetro', N'Cardio', N'Secuencia piernas - tronco - brazos.')
) AS v(Name, MuscleGroup, Description)
WHERE NOT EXISTS (SELECT 1 FROM dbo.ExerciseCatalog c WHERE c.Name = v.Name);
END
GO

-- Plantillas de rutina: 5 filas
IF OBJECT_ID('dbo.RoutineTemplates','U') IS NOT NULL
BEGIN
INSERT INTO dbo.RoutineTemplates (CoachID, TemplateName, Goal)
SELECT u.UserID, v.TemplateName, v.Goal
FROM (VALUES
    (N'andres.villacis1@demo.slimminggym.com', N'Hipertrofia 4 días - Intermedio', N'Ganancia de masa muscular en 12 semanas'),
    (N'gabriela.moreta2@demo.slimminggym.com', N'Pérdida de grasa - 3 días', N'Reducción de porcentaje graso con trabajo metabólico'),
    (N'kevin.zambrano3@demo.slimminggym.com', N'Funcional para principiantes', N'Adaptación anatómica y técnica básica'),
    (N'paul.mendoza4@demo.slimminggym.com', N'Readaptación - bajo impacto', N'Retomar la actividad física sin carga articular'),
    (N'andres.villacis1@demo.slimminggym.com', N'Fuerza básica 5x5', N'Progresión de carga en movimientos compuestos')
) AS v(Email, TemplateName, Goal)
JOIN dbo.Users u ON u.Email = v.Email;
END
GO

